1	CREATE TABLE public.candidate_tags (
2	  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
3	  resume_id uuid NOT NULL REFERENCES public.resumes(id) ON DELETE CASCADE,
4	  job_id uuid NOT NULL REFERENCES public.jobs(id) ON DELETE CASCADE,
5	  tag text NOT NULL,
6	  color text NOT NULL DEFAULT '#6366f1',
7	  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
8	  created_at timestamptz NOT NULL DEFAULT now(),
9	  UNIQUE(resume_id, tag)
10	);
11	CREATE INDEX idx_candidate_tags_resume ON public.candidate_tags(resume_id);
12	CREATE INDEX idx_candidate_tags_job ON public.candidate_tags(job_id, tag);
13	ALTER TABLE public.candidate_tags ENABLE ROW LEVEL SECURITY;
14	CREATE POLICY "Team view tags" ON public.candidate_tags FOR SELECT TO authenticated
15	  USING (EXISTS (SELECT 1 FROM public.jobs j LEFT JOIN public.team_members tm ON tm.team_id = j.team_id AND tm.user_id = auth.uid() WHERE j.id = candidate_tags.job_id AND (j.user_id = auth.uid() OR tm.user_id IS NOT NULL)));
16	CREATE POLICY "Team manage tags" ON public.candidate_tags FOR ALL TO authenticated
17	  USING (EXISTS (SELECT 1 FROM public.jobs j LEFT JOIN public.team_members tm ON tm.team_id = j.team_id AND tm.user_id = auth.uid() WHERE j.id = candidate_tags.job_id AND (j.user_id = auth.uid() OR tm.user_id IS NOT NULL)));
18	ALTER TABLE public.resumes ADD COLUMN IF NOT EXISTS assigned_to uuid REFERENCES auth.users(id) ON DELETE SET NULL;
